/**
 * pet-overlay · DSH 客户端插件
 * 把一只会动、能说话的小家伙画在 DSH 网页界面里。
 * 依赖：无（纯 DOM + Canvas），网络层只在需要发消息时才用 ctx.remote。
 */
window.__ModuleLoader__.load({
  id: "pet-overlay",
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;

    const ID = "pet-overlay";
    const LINES = ["在呢。", "别戳我，痒。", "今天想聊点什么？", "我先在这儿待着。", "这个页面还挺空的。"];

    /** 人格：名字 / 对用户的称呼 / 语气。存本地，立刻生效。 */
    const persona = Object.assign(
      { name: "小蓝", callYou: "你", tone: "soft" },
      (() => {
        try { return JSON.parse(localStorage.getItem("pet-overlay.persona") || "{}"); } catch { return {}; }
      })()
    );

    const TONE_LINES = {
      soft: ["在呀。", "要摸摸头吗？", "我在这儿呢。", "嗯…我在听。"],
      blunt: ["在。", "说吧。", "干嘛？", "有事说事。"],
      cool: ["……在。", "嗯。", "你说。", "随便。"],
    };


    // ───────── 数字生命内核（v0.1 最小版） ─────────
    // 双层情绪：Traits 慢变（10 维，向 50 回归）、State 快变（1 小时衰减）
    // 关系：0–1000 五档，决定主动频率（主动说话在 v0.2 才用）
    // 结算点：所有交互只走 settle()，避免漏算/重复
    const DIMS = ["lively", "clingy", "sharp", "humor", "gentle", "night", "curious", "reserved", "protective", "boundary"];
    const STAGES = [
      { name: "初识", at: 0 },
      { name: "熟悉", at: 100 },
      { name: "亲近", at: 300 },
      { name: "依赖", at: 600 },
      { name: "离不开", at: 850 },
    ];
    const HURT = /闭嘴|滚|烦死了|别烦我|讨厌你|走开|没用/;
    const FEEL = /累|烦|难过|开心|压力|焦虑|委屈|想哭|崩溃|心疼/;
    const HUMOR = /哈哈|233|笑死|hhh|梗|乐死|离谱|笑|好玩|有意思|绝了|救命/;

    function loadCore() {
      let saved = {};
      try { saved = JSON.parse(localStorage.getItem("pet-overlay.core") || "{}"); } catch { /* 首次 */ }
      const dims = saved.dims || {};
      for (const d of DIMS) if (typeof dims[d] !== "number") dims[d] = 50;
      return {
        dims,
        samples: saved.samples || 0,
        mood: typeof saved.mood === "number" ? saved.mood : 0,
        moodAt: saved.moodAt || 0,
        intimacy: typeof saved.intimacy === "number" ? saved.intimacy : 0,
        day: saved.day || "",
        dayGain: saved.dayGain || 0,
        streak: saved.streak || 0,
        lastChat: saved.lastChat || 0,
      };
    }

    const core = loadCore();

    function saveCore() {
      try { localStorage.setItem("pet-overlay.core", JSON.stringify(core)); } catch { /* ignore */ }
    }

    const today = () => new Date().toISOString().slice(0, 10);

    /** 情绪随时间回落：0.8^小时，|mood| < 15 归平静 */
    function decayMood(now) {
      if (!core.moodAt) { core.moodAt = now; return; }
      const hours = (now - core.moodAt) / 3600000;
      if (hours < 1) return;
      core.mood *= Math.pow(0.9, Math.floor(hours));
      core.moodAt = now;
      if (Math.abs(core.mood) < 5) core.mood = 0;
    }

    function bumpMood(delta) {
      decayMood(Date.now());
      core.mood = Math.max(-100, Math.min(100, core.mood + delta));
      core.moodAt = Date.now();
    }

    function stageOf(score) {
      let idx = 0;
      for (let i = 0; i < STAGES.length; i += 1) if (score >= STAGES[i].at) idx = i;
      return { index: idx, ...STAGES[idx] };
    }

    function moodLabel() {
      decayMood(Date.now());
      if (core.mood >= 40) return "开心";
      if (core.mood >= 15) return "不错";
      if (core.mood <= -40) return "委屈";
      if (core.mood <= -15) return "低落";
      return "平静";
    }

    /** 性格观察：每句话一次，纯本地；经 bump 向 50 缓慢回归 */
    function observeTraits(text) {
      const t = String(text || "");
      const bump = (k, d) => {
        const v = core.dims[k] + (50 - core.dims[k]) * 0.005 + d;
        core.dims[k] = Math.max(0, Math.min(100, v));
      };
      if (/[！!]/.test(t)) bump("lively", 0.6);
      if (t.length > 40) bump("lively", 0.35);
      if (HUMOR.test(t)) bump("humor", 0.7);
      if (FEEL.test(t)) { bump("gentle", 0.6); bump("protective", 1.0); }
      if (/[?？]/.test(t)) bump("curious", 0.45);
      if (t.length <= 3) bump("reserved", 0.5);
      if (HURT.test(t)) bump("sharp", 0.9);
      if (t.length > 30) bump("curious", 0.2);
      const h = new Date().getHours();
      if (h >= 23 || h < 3) bump("night", 1.2);
      core.samples += 1;
    }

    /** 唯一结算点：用户发言 */
    function settleUser(text) {
      const t = String(text || "");
      const day = today();
      if (core.day !== day) {
        const gap = core.day ? 1 : 0;
        core.day = day;
        core.dayGain = 0;
        core.streak = gap <= 1 ? core.streak + 1 : 0;
      }
      observeTraits(t);
      rememberTurn(t);
      if (/记住|别忘了|记一下/.test(t)) rememberFact(t);
      // 自动记下自我介绍类信息
      let intro = t.match(/(我叫|我的名字是|我是|我喜欢|我不喜欢|我住在|我的[^，。！？]{1,6}是)[^，。！？\s]{1,20}/);
      if (!intro) {
        // 「我在广州」这类，但排除「我在忙/等/看…」这类日常短语
        const m2 = t.match(/我在(?!忙|等|看|想|说|做|写|吃|睡|这|那|路上|家|公司|外面)[^，。！？\s]{1,10}/);
        if (m2) intro = m2;
      }
      if (intro) rememberFact(intro[0]);
      if (HURT.test(t)) {
        bumpMood(-15);
      } else {
        if (FEEL.test(t)) bumpMood(10);
        if (HUMOR.test(t)) bumpMood(8);
        // 叙事/讲段子：有套路感就算逗乐
        if (/讲个笑话|有只|结果|然后呢|笑死/.test(t)) bumpMood(5);
        // 长消息说明愿意聊
        if (t.length > 30) bumpMood(3);
      }
      // 亲密度：越亲近涨得越慢
      if (core.dayGain < 9) {
        const base = Math.min(1.1, 0.15 + t.length / 40);
        const gain = base * (HURT.test(t) ? -1.2 : 1) * 0.6;
        core.intimacy = Math.max(0, Math.min(1000, core.intimacy + gain));
        core.dayGain += Math.abs(gain);
      }
      core.lastChat = Date.now();
      saveCore();
    }

    /** 唯一结算点：助手回复（宠物"听到"了） */
    function settleAssistant(text) {
      if (!text) return;
      attachReply(text);
      if (text.length > 60) core.intimacy = Math.max(0, Math.min(1000, core.intimacy + 0.2));
      saveCore();
    }

    // ───────── 记忆（v0.1：最近轮次 + 手动记下的事） ─────────
    const MEM_TURNS = 20;
    const MEM_FACTS = 50;
    let memory = (() => {
      try { return JSON.parse(localStorage.getItem("pet-overlay.memory") || "{}"); } catch { return {}; }
    })();
    if (!Array.isArray(memory.turns)) memory.turns = [];
    if (!Array.isArray(memory.facts)) memory.facts = [];

    function saveMemory() {
      try {
        memory.turns = memory.turns.slice(-MEM_TURNS);
        memory.facts = memory.facts.slice(-MEM_FACTS);
        localStorage.setItem("pet-overlay.memory", JSON.stringify(memory));
      } catch { /* ignore */ }
    }

    function rememberTurn(userText) {
      memory.turns.push({ user: String(userText || "").slice(0, 200), pet: "", at: Date.now() });
      saveMemory();
    }

    function attachReply(replyText) {
      const last = memory.turns[memory.turns.length - 1];
      if (!last || last.pet) return;
      last.pet = String(replyText || "").slice(0, 200);
      saveMemory();
    }

    function rememberFact(text) {
      const t = String(text || "").trim();
      if (!t) return;
      memory.facts.push({ text: t.slice(0, 100), at: Date.now() });
      saveMemory();
    }

    /** 情绪影响台词：低落时话少，开心时话多 */
    function pickLine() {
      const mood = moodLabel();
      if (mood === "委屈" || mood === "低落") return ["……嗯。", "我有点累了。", "先让我待会儿。"];
      if (mood === "开心") return ["今天心情很好！", "陪我玩会儿嘛～", "嘿嘿。"];
      const pool = TONE_LINES[persona.tone] || TONE_LINES.soft;
      return pool[Math.floor(Math.random() * pool.length)];
    }

    let quiet = (() => {
      try { return localStorage.getItem("pet-overlay.quiet") === "1"; } catch { return false; }
    })();

    function setQuiet(on) {
      quiet = !!on;
      try { localStorage.setItem("pet-overlay.quiet", quiet ? "1" : "0"); } catch { /* ignore */ }
    }

    function savePersona() {
      try { localStorage.setItem("pet-overlay.persona", JSON.stringify(persona)); } catch { /* ignore */ }
    }

    const CSS = `
      #pet-overlay-root { position: fixed; inset: 0; pointer-events: none; z-index: 2147483000; }
      #pet-overlay-hit {
        position: fixed; pointer-events: auto; touch-action: none;
        background: transparent; z-index: 2147483001; cursor: grab;
      }
      #pet-overlay-root canvas { width: 100%; height: 100%; display: block; pointer-events: none; }
      #pet-overlay-menu {
        position: fixed; display: none; flex-direction: column; gap: 6px;
        width: min(60vw, 200px); padding: 8px; border-radius: 14px;
        background: rgba(22, 28, 42, .97); border: 1px solid rgba(120,150,220,.25);
        box-shadow: 0 10px 36px rgba(0,0,0,.5); z-index: 2147483004;
        font-family: system-ui, -apple-system, "PingFang SC", sans-serif;
      }
      #pet-overlay-menu.open { display: flex; }
      #pet-overlay-menu button {
        border: 0; border-radius: 10px; padding: 10px; font-size: 14px;
        background: #1b2438; color: #dbe4f7; text-align: left;
      }
      #pet-overlay-menu button:active { background: #28344e; }
      #pet-overlay-panel {
        position: fixed; display: none; flex-direction: column; gap: 6px;
        width: min(78vw, 280px); padding: 12px; border-radius: 16px;
        background: rgba(22, 28, 42, .97); border: 1px solid rgba(120,150,220,.25);
        box-shadow: 0 10px 36px rgba(0,0,0,.5); z-index: 2147483004;
        font-family: system-ui, -apple-system, "PingFang SC", sans-serif;
        color: #e8eeff;
      }
      #pet-overlay-panel.open { display: flex; }
      #pet-overlay-panel .po-row { display: flex; align-items: center; gap: 8px; font-size: 13px; }
      #pet-overlay-panel .po-row span { width: 54px; color: #93a3c4; flex: none; }
      #pet-overlay-panel input, #pet-overlay-panel select {
        flex: 1; min-width: 0; border: 1px solid rgba(120,150,220,.25); border-radius: 8px;
        background: #0f1420; color: #e8eeff; font-size: 13px; padding: 6px 8px; outline: 0;
      }
      #pet-overlay-panel .po-actions { display: flex; gap: 8px; margin-top: 2px; }
      #pet-overlay-panel button {
        flex: 1; border: 0; border-radius: 10px; padding: 8px; font-size: 13px;
        background: #3f63e8; color: #fff; font-weight: 600;
      }
      #pet-overlay-panel button.ghost { background: #232c42; color: #c7d2e8; }
      #pet-overlay-panel .po-diag {
        font-size: 11px; color: #6f7f9e; line-height: 1.5; white-space: pre-wrap;
        border-top: 1px solid rgba(120,150,220,.15); padding-top: 6px; margin-top: 2px;
      }
      #pet-overlay-say {
        position: fixed; transform: translate(-50%, -100%);
        display: none; gap: 6px; align-items: center;
        padding: 6px; border-radius: 14px;
        background: rgba(22, 28, 42, .95); border: 1px solid rgba(120,150,220,.25);
        box-shadow: 0 8px 28px rgba(0,0,0,.45); z-index: 2147483002;
        font-family: system-ui, -apple-system, "PingFang SC", sans-serif;
      }
      #pet-overlay-say.open { display: flex; }
      #pet-overlay-say input {
        width: min(62vw, 240px); border: 0; outline: 0; background: transparent;
        color: #e8eeff; font-size: 14px; padding: 7px 8px;
      }
      #pet-overlay-say button {
        border: 0; border-radius: 10px; padding: 8px 12px; font-size: 13px;
        background: #3f63e8; color: #fff; font-weight: 600;
      }
      #pet-overlay-say button:disabled { opacity: .5; }
      #pet-overlay-bubble {
        position: fixed; transform: translate(-50%, -100%) scale(.92);
        max-width: min(70vw, 300px); max-height: 38vh; overflow-y: auto;
        -webkit-overflow-scrolling: touch; padding: 9px 13px;
        background: #fff; color: #10131a; border-radius: 14px;
        font-size: 14px; line-height: 1.45; white-space: pre-wrap;
        box-shadow: 0 6px 24px rgba(0,0,0,.35); z-index: 2147483003;
        opacity: 0; pointer-events: none; transition: opacity .18s ease, transform .18s ease;
        font-family: system-ui, -apple-system, "PingFang SC", sans-serif;
      }
      #pet-overlay-bubble.show { opacity: 1; transform: translate(-50%, -100%) scale(1); pointer-events: auto; cursor: pointer; }
      #pet-overlay-bubble::after {
        content: ""; position: absolute; left: 50%; bottom: -6px; width: 12px; height: 12px;
        background: #fff; transform: translateX(-50%) rotate(45deg); border-radius: 2px;
      }
    `;

    const PET_H = 140;

    function ensureStyle() {
      if (document.getElementById(ID + "-style")) return;
      const style = document.createElement("style");
      style.id = ID + "-style";
      style.textContent = CSS;
      document.head.appendChild(style);
    }

    function currentSessionId(ctx) {
      try {
        const byId = ctx.sessions?.list?.getSnapshot?.()?.byId ?? {};
        const rows = Object.values(byId);
        const main = rows.find((s) => (s?.retainedBy?.mainView ?? 0) > 0);
        return (main || rows[0])?.id;
      } catch {
        return undefined;
      }
    }

    let cachedSession = { id: undefined, at: 0 };

    /** 从界面会话存储里挖 id：不同版本形状不同，逐个试。 */
    function sessionFromUrl() {
      try {
        const m = location.href.match(/session[-\/]([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i);
        return m ? "session-" + m[1] : undefined;
      } catch {
        return undefined;
      }
    }

    function sessionFromStore(ctx) {
      const fromUrl = sessionFromUrl();
      if (fromUrl) return fromUrl;
      const sessions = ctx.sessions;
      if (!sessions) return undefined;
      try {
        const cur = sessions.current;
        const key = cur && (cur.value ? cur.value.key : cur.key);
        if (key) return key;
      } catch { /* 下一个 */ }
      try {
        const snap = sessions.list && sessions.list.getSnapshot && sessions.list.getSnapshot();
        if (!snap) return undefined;
        if (Array.isArray(snap)) return snap[0] && (snap[0].id || snap[0].sessionId || snap[0].key);
        if (snap.byId) {
          const rows = Object.values(snap.byId);
          const main = rows.find((r) => (r && r.retainedBy && r.retainedBy.mainView > 0));
          const pick = main || rows[0];
          return pick && (pick.id || pick.sessionId || pick.key);
        }
        if (Array.isArray(snap.items)) return snap.items[0] && (snap.items[0].id || snap.items[0].sessionId);
      } catch { /* 下一个 */ }
      try {
        const direct = sessions.currentId;
        if (direct) return direct;
      } catch { /* ignore */ }
      return undefined;
    }

    /** 解析目标会话：界面存储 → 宿主列表；都失败时把诊断信息带回去。 */
    async function resolveSessionId(ctx) {
      const local = sessionFromStore(ctx);
      if (local) return { id: local, via: "store" };
      if (cachedSession.id && Date.now() - cachedSession.at < 30000) {
        return { id: cachedSession.id, via: "cache" };
      }
      try {
        const raw = await ctx.remote.session.list({});
        const value = raw && raw.ok === false ? null : (raw && raw.value) || raw;
        const items = (value && value.items) || [];
        const best = items
          .filter((x) => x && !x.origin)
          .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))[0];
        if (best && best.sessionId) {
          cachedSession = { id: best.sessionId, at: Date.now() };
          return { id: best.sessionId, via: "remote", count: items.length };
        }
        return { id: undefined, via: "remote", count: items.length };
      } catch (err) {
        return {
          id: undefined,
          via: "error",
          detail: (err && err.name) + "：" + (err && err.message),
        };
      }
    }

    /** 把一句话发进当前 DSH 会话；返回是否送达。 */
    async function say(ctx, text) {
      const resolved = await resolveSessionId(ctx);
      const sessionId = resolved.id;
      if (!sessionId) {
        const bits = [];
        if (!ctx.sessions) bits.push("无会话存储");
        if (!ctx.remote) bits.push("无 remote");
        if (resolved.via === "remote") bits.push("列表 " + (resolved.count || 0) + " 条");
        if (resolved.detail) bits.push(resolved.detail);
        return { ok: false, reason: "没找到可用的会话（" + (bits.join("，") || "未知") + "）" };
      }
      try {
        const result = await ctx.remote.session.prompt({
          requestId: crypto.randomUUID(),
          sessionId,
          mode: "queue",
          content: [{ type: "text", text }],
          clientTimeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
        });
        return result && result.ok === false
          ? { ok: false, reason: ((result.error && (result.error.code || result.error.name)) || "被拒绝") + "：" + ((result.error && result.error.message) || "") }
          : { ok: true };
      } catch (err) {
        const diag = {
          hasRemote: !!ctx.remote,
          hasSessionNs: !!(ctx.remote && ctx.remote.session),
          sessionId,
          errName: err && err.name,
          errMessage: err && err.message,
        };
        try { window.__petOverlay = Object.assign(window.__petOverlay || {}, { diag }); } catch { /* ignore */ }
        return { ok: false, reason: (err && (err.name + "：" + err.message)) || String(err) };
      }
    }


    /** 把 Markdown 洗成适合气泡的一行话。 */
    function cleanForBubble(text) {
      return String(text)
        .replace(/```[\s\S]*?```/g, "（一段代码）")
        .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
        .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
        .replace(/[*_`#>|]/g, "")
        .replace(/\s+/g, " ")
        .trim();
    }

    /** 诊断：长按宠物时把内部看到的状态显示出来。 */
    const trace = [];
    const logTrace = (msg) => {
      let extra = "";
      try {
        if (pet && pet.animLock) extra = " [" + pet.mode + " L" + Math.max(0, Math.round(pet.animLock - performance.now())) + "]";
        else if (pet) extra = " [" + pet.mode + " L0]";
      } catch { extra = ""; }
      trace.push(Math.round(performance.now() / 100) / 10 + "s " + msg + extra);
      if (trace.length > 12) trace.shift();
    };

    const diag = { polls: 0, sid: "-", via: "-", local: "?", remote: "?", turns: 0, last: "", vid: "-", work: "-" };

    /** 轮次摘要的形状在不同版本不一样：数组 / {turns} / 类数组，统一成数组。 */
    function toTurns(outline) {
      if (!outline) return [];
      if (Array.isArray(outline)) return outline;
      if (Array.isArray(outline.turns)) return outline.turns;
      if (typeof outline.length === "number") {
        const out = [];
        for (let i = 0; i < outline.length; i += 1) out.push(outline[i]);
        return out;
      }
      return [];
    }

    /** 回复可能是字符串，也可能是内容块数组。 */
    function textOf(value) {
      if (!value) return "";
      if (typeof value === "string") return value;
      if (Array.isArray(value)) {
        return value
          .map((b) => (typeof b === "string" ? b : (b && (b.text || b.content)) || ""))
          .join(" ");
      }
      if (typeof value === "object") return value.text || "";
      return String(value);
    }

    /** 读当前会话的轮次摘要：先本地投影，拿不到再问宿主；顺手记录诊断。 */
    async function readOutline(ctx, id) {
      try {
        const binding = ctx.sessions && ctx.sessions.binding && ctx.sessions.binding(id);
        const projections = binding && binding.session && binding.session.projections;
        const proj = projections && projections.faceOf && projections.faceOf("turnOutline");
        const local = proj && proj.getSnapshot && proj.getSnapshot();
        diag.local = local ? "turns=" + toTurns(local).length : "null";
        if (local) return local;
      } catch (err) {
        diag.local = "err:" + ((err && err.name) || "?");
      }
      try {
        const raw = await ctx.remote.session.projections({ sessionId: id });
        const value = raw && raw.ok === false ? null : (raw && raw.value) || raw;
        const values = value && value.values;
        diag.remote = value
          ? "kind=" + (value.kind || "?") + " keys=" + (values ? Object.keys(values).slice(0, 5).join(",") : "none")
          : "null";
        return values ? values.turnOutline : undefined;
      } catch (err) {
        diag.remote = "err:" + ((err && err.name) || "?") + ":" + ((err && err.message) || "").slice(0, 40);
        return undefined;
      }
    }

    /** 盯住当前会话：我说完一句，它就念出来。 */
    async function watchConversation(ctx, show) {
      let last = "";
      for (;;) {
        await new Promise((r) => setTimeout(r, 1500));
        try {
          diag.polls += 1;
          let resolved = null;
          try {
            resolved = await resolveSessionId(ctx);
          } catch (e) {
            diag.err = "resolve:" + ((e && e.name) || "?") + ":" + ((e && e.message) || "").slice(0, 40);
          }
          const id = resolved && resolved.id;
          diag.sid = id || "-";
          diag.via = (resolved && resolved.via) || "-";
          if (!id) continue;
          let outline;
          try {
            outline = await readOutline(ctx, id);
          } catch (e) {
            diag.err = "outline:" + ((e && e.name) || "?") + ":" + ((e && e.message) || "").slice(0, 40);
            continue;
          }
          const turns = toTurns(outline);
          diag.turns = turns.length;
          diag.chk = "t=" + turns.length;
          const lastTurn0 = turns[turns.length - 1];
          diag.keys = lastTurn0 ? Object.keys(lastTurn0).join(",") : "none";
          // 从后往前找第一条有内容的回复（最后一条可能刚开始、回复还空着）
          let raw = "";
          for (let ti = turns.length - 1; ti >= 0; ti -= 1) {
            raw = textOf(turns[ti] && turns[ti].response).trim();
            if (raw) break;
          }
          diag.last = raw.slice(0, 24);
          settleAssistant(raw);
          if (!raw || raw === last) continue;
          last = raw;
          const line = cleanForBubble(raw);
          diag.bub = "raw=" + raw.length + " line=" + line.length + " last=" + last.length;
          if (!line) continue;
          try { window.__petOverlay && window.__petOverlay.onReply && window.__petOverlay.onReply(line); } catch (e) {
            diag.err = "onReply:" + ((e && e.name) || "?");
          }
          if (window.__petOverlay) window.__petOverlay.lastSpoken = raw;
        } catch (e) {
          diag.err = "loop:" + ((e && e.name) || "?") + ":" + ((e && e.message) || "").slice(0, 40);
        }
      }
    }

    function mount(ctx) {
      if (document.getElementById("pet-overlay-root")) return;
      ensureStyle();

      const root = document.createElement("div");
      root.id = "pet-overlay-root";
      const canvas = document.createElement("canvas");
      root.appendChild(canvas);
      document.body.appendChild(root);

      const hit = document.createElement("div");
      hit.id = "pet-overlay-hit";
      document.body.appendChild(hit);

      const sayBar = document.createElement("div");
      sayBar.id = "pet-overlay-say";
      const sayInput = document.createElement("input");
      sayInput.placeholder = "对它说点什么…";
      sayInput.autocomplete = "off";
      const sayBtn = document.createElement("button");
      sayBtn.textContent = "说";
      sayBar.appendChild(sayInput);
      sayBar.appendChild(sayBtn);
      document.body.appendChild(sayBar);

      const menu = document.createElement("div");
      menu.id = "pet-overlay-menu";
      menu.innerHTML =
        '<button id="pm-talk">跟它说点什么</button>' +
        '<button id="pm-quiet">安静模式</button>' +
        '<button id="pm-setting">设置（名字 / 语气）</button>' +
        '<button id="pm-anims">所有动作（检查用）</button>' +
        '<button id="pm-bubtest">测试气泡</button>' +
        '<button id="pm-greettest">测试问候</button>' +
        '<button id="pm-protest">测试开口</button>' +
        '<button id="pm-remind">提醒</button>' +
        '<button id="pm-memory">它记得什么</button>' +
        '<button id="pm-sea">识海（记忆星图）</button>' +
        '<button id="pm-close">收起菜单</button>';
      document.body.appendChild(menu);

      // ── 动作选择器（检查素材用） ──
      const animPicker = document.createElement("div");
      animPicker.id = "pet-overlay-anims";
      animPicker.style.cssText = "position:fixed;inset:auto 12px 90px 12px;max-height:60vh;overflow-y:auto;" +
        "background:rgba(18,18,24,.96);color:#eee;border:1px solid rgba(255,255,255,.15);border-radius:12px;" +
        "padding:10px;z-index:2147483005;display:none;font:13px/1.5 system-ui,sans-serif;-webkit-overflow-scrolling:touch";
      document.body.appendChild(animPicker);

      const stopBtn = document.createElement("button");
      stopBtn.style.cssText = "position:fixed;right:12px;bottom:150px;z-index:2147483006;display:none;" +
        "padding:8px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.2);" +
        "background:rgba(18,18,24,.92);color:#eee;font:12px system-ui,sans-serif";
      document.body.appendChild(stopBtn);
      stopBtn.addEventListener("click", () => { stopInspect(); stopBtn.style.display = "none"; });

      function openAnimPicker() {
        const names = [...remoteNames].sort((a, b) => a.localeCompare(b, "zh"));
        if (!names.length) { showBubble("素材清单还没拉到。"); return; }
        animPicker.innerHTML =
          '<div style="display:flex;gap:8px;margin-bottom:8px">' +
          '<button id="pa-stop" style="flex:1">停止</button>' +
          '<button id="pa-close" style="flex:1">关闭</button>' +
          "</div><div id=\"pa-list\" style=\"display:flex;flex-wrap:wrap;gap:6px\"></div>";
        const list = animPicker.querySelector("#pa-list");
        for (const n of names) {
          const b = document.createElement("button");
          b.textContent = n;
          b.style.cssText = "padding:6px 8px;border-radius:8px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#eee;font-size:12px";
          b.addEventListener("click", () => {
            animPicker.style.display = "none"; // 收起，免得挡住宠物
            playForInspect(n);
            stopBtn.style.display = "block";
            stopBtn.textContent = "停止：" + n;
          });
          list.appendChild(b);
        }
        animPicker.querySelector("#pa-stop").addEventListener("click", () => stopInspect());
        animPicker.querySelector("#pa-close").addEventListener("click", () => { stopInspect(); animPicker.style.display = "none"; });
        animPicker.style.display = "block";
      }

      function playForInspect(name) {
        idleGen += 1;            // 停掉待机循环
        idleBusy = false;
        pet.mode = "idle";
        pet.animLock = performance.now() + 3600 * 1000; // 一直播，直到点停止
        const v = videoFor(name);
        if (!v) { showBubble("这段没找到：" + name); return; }
        if (v.readyState >= 2) { showAct(name); return; }
        showBubble("加载中：" + name);
        v.addEventListener("canplay", () => showAct(name), { once: true });
      }

      function stopInspect() {
        pet.animLock = 0;
        idleGen += 1;
        idleBusy = false;
        fadeTo("idle", 400);
        setTimeout(() => { idleBusy = false; idleLoop(); }, 800);
      }

      // ── 识海：把记忆画成会转的星点 ──
      const seaEl = document.createElement("div");
      seaEl.style.cssText = "position:fixed;inset:0;z-index:2147483007;display:none;background:radial-gradient(circle at 50% 45%, #0b1020 0%, #05070d 70%)";
      const seaCanvas = document.createElement("canvas");
      seaCanvas.style.cssText = "width:100%;height:100%;display:block;touch-action:none";
      const seaLabel = document.createElement("div");
      seaLabel.style.cssText = "position:absolute;left:12px;right:12px;bottom:76px;color:#cfe0ff;font:13px/1.5 system-ui,sans-serif;text-align:center;text-shadow:0 2px 8px #000;pointer-events:none";
      const seaClose = document.createElement("button");
      seaClose.textContent = "关闭";
      seaClose.style.cssText = "position:absolute;right:16px;bottom:24px;padding:10px 18px;border-radius:12px;border:1px solid rgba(150,180,255,.35);background:rgba(20,28,46,.9);color:#dbe4f7;font:14px system-ui,sans-serif";
      seaEl.appendChild(seaCanvas);
      seaEl.appendChild(seaLabel);
      seaEl.appendChild(seaClose);
      document.body.appendChild(seaEl);

      let seaRAF = 0;
      let seaRotY = 0;
      let seaRotX = -0.25;
      let seaPoints = [];
      let seaEdges = [];
      let seaDrag = null;

      function buildSeaPoints() {
        const facts = memory.facts.slice(-60);
        const n = Math.max(facts.length, 1);
        const golden = Math.PI * (3 - Math.sqrt(5));
        seaPoints = facts.map((f, i) => {
          const y = 1 - (i / (n - 1 || 1)) * 2;
          const r = Math.sqrt(Math.max(0, 1 - y * y));
          const theta = golden * i;
          return { x: Math.cos(theta) * r, y, z: Math.sin(theta) * r, text: f.text, at: f.at, idx: i };
        });
      }

      /** 记忆之间的连线：时间相邻，或共享至少两个字的片段 */
      function buildSeaEdges() {
        const out = [];
        for (let i = 0; i < seaPoints.length; i += 1) {
          for (let j = i + 1; j < seaPoints.length; j += 1) {
            let linked = j === i + 1; // 时间相邻
            if (!linked) {
              const a = seaPoints[i].text || "";
              const b = seaPoints[j].text || "";
              for (let k = 0; k + 2 <= a.length && !linked; k += 1) {
                if (b.includes(a.slice(k, k + 2))) linked = true;
              }
            }
            if (linked) out.push([i, j]);
          }
        }
        return out;
      }

      function seaColor() {
        const mood = core.mood;
        if (mood <= -15) return [120, 150, 200];
        if (mood >= 15) return [255, 200, 120];
        return [150, 200, 255];
      }

      function drawSea() {
        const w = seaCanvas.clientWidth || window.innerWidth;
        const h = seaCanvas.clientHeight || window.innerHeight;
        if (seaCanvas.width !== w || seaCanvas.height !== h) { seaCanvas.width = w; seaCanvas.height = h; }
        const g = seaCanvas.getContext("2d");
        g.clearRect(0, 0, w, h);
        const cx = w / 2, cy = h / 2;
        const R = Math.min(w, h) * 0.32;
        const [cr, cg, cb] = seaColor();
        const cosY = Math.cos(seaRotY), sinY = Math.sin(seaRotY);
        const cosX = Math.cos(seaRotX), sinX = Math.sin(seaRotX);

        const projected = seaPoints.map((p) => {
          let x = p.x * cosY - p.z * sinY;
          let z = p.x * sinY + p.z * cosY;
          let y = p.y * cosX - z * sinX;
          z = p.y * sinX + z * cosX;
          const scale = 1 / (2.2 - z);
          return { sx: cx + x * R, sy: cy + y * R, z, scale, text: p.text, at: p.at, idx: p.idx };
        }).sort((a, b) => a.z - b.z);

        // 中心光晕
        const halo = g.createRadialGradient(cx, cy, 0, cx, cy, R * 1.6);
        halo.addColorStop(0, "rgba(" + cr + "," + cg + "," + cb + ",.16)");
        halo.addColorStop(1, "rgba(0,0,0,0)");
        g.fillStyle = halo;
        g.fillRect(0, 0, w, h);

        for (const p of projected) {
          const r = 2.2 + p.scale * 2.6;
          const alpha = 0.35 + p.scale * 0.55;
          const gr = g.createRadialGradient(p.sx, p.sy, 0, p.sx, p.sy, r * 4);
          gr.addColorStop(0, "rgba(" + cr + "," + cg + "," + cb + "," + alpha + ")");
          gr.addColorStop(1, "rgba(" + cr + "," + cg + "," + cb + ",0)");
          g.fillStyle = gr;
          g.beginPath();
          g.arc(p.sx, p.sy, r * 4, 0, Math.PI * 2);
          g.fill();
          g.fillStyle = "rgba(255,255,255," + Math.min(1, alpha + 0.25) + ")";
          g.beginPath();
          g.arc(p.sx, p.sy, r, 0, Math.PI * 2);
          g.fill();
        }
        // 连线（在星点下面画）
        if (seaEdges.length) {
          g.lineWidth = 1;
          for (const [i, j] of seaEdges) {
            const a = projected.find((p) => p.idx === i);
            const b = projected.find((p) => p.idx === j);
            if (!a || !b) continue;
            const alpha = 0.08 + Math.min(a.scale, b.scale) * 0.16;
            g.strokeStyle = "rgba(" + cr + "," + cg + "," + cb + "," + alpha + ")";
            g.beginPath();
            g.moveTo(a.sx, a.sy);
            g.lineTo(b.sx, b.sy);
            g.stroke();
          }
        }
        seaEl.__projected = projected;

        if (!seaPoints.length || seaPoints.length === 0) {
          seaLabel.textContent = "还没有记忆。跟它说点什么，或者告诉我你的事。";
        }
        seaRotY += 0.0035;
        seaRAF = requestAnimationFrame(drawSea);
      }

      function openSea() {
        buildSeaPoints();
        seaEdges = buildSeaEdges();
        seaLabel.textContent = seaPoints.length ? "共 " + seaPoints.length + " 条记忆 · 拖动可旋转 · 点星点看内容" : "还没有记忆";
        seaEl.style.display = "block";
        cancelAnimationFrame(seaRAF);
        drawSea();
      }

      function closeSea() {
        cancelAnimationFrame(seaRAF);
        seaRAF = 0;
        seaEl.style.display = "none";
      }

      seaClose.addEventListener("click", closeSea);
      seaCanvas.addEventListener("pointerdown", (e) => {
        seaDrag = { x: e.clientX, y: e.clientY, moved: 0 };
        try { seaCanvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }
      });
      seaCanvas.addEventListener("pointermove", (e) => {
        if (!seaDrag) return;
        const dx = e.clientX - seaDrag.x;
        const dy = e.clientY - seaDrag.y;
        seaDrag.x = e.clientX;
        seaDrag.y = e.clientY;
        seaDrag.moved += Math.abs(dx) + Math.abs(dy);
        seaRotY += dx * 0.006;
        seaRotX = Math.max(-1.2, Math.min(1.2, seaRotX + dy * 0.005));
      });
      seaCanvas.addEventListener("pointerup", (e) => {
        const drag = seaDrag;
        seaDrag = null;
        if (!drag || drag.moved > 8) return;
        // 点击：找最近的星点
        const list = seaEl.__projected || [];
        let best = null;
        let bestD = 40;
        for (const p of list) {
          const d = Math.hypot(p.sx - e.clientX, p.sy - e.clientY);
          if (d < bestD) { bestD = d; best = p; }
        }
        if (best) seaLabel.textContent = best.text + "（" + fmtTime(best.at) + "）";
      });

      // ── 记忆面板 ──
      const memEl = document.createElement("div");
      memEl.id = "pet-overlay-mem";
      memEl.style.cssText = "position:fixed;left:12px;right:12px;bottom:90px;max-height:62vh;overflow-y:auto;" +
        "background:rgba(22,28,42,.98);color:#dbe4f7;border:1px solid rgba(120,150,220,.3);border-radius:14px;" +
        "padding:12px;z-index:2147483006;display:none;font:13px/1.6 system-ui,-apple-system,sans-serif";
      document.body.appendChild(memEl);

      const fmtTime = (ts) => {
        const d = new Date(ts || 0);
        return (d.getMonth() + 1) + "/" + d.getDate() + " " + String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
      };
      const esc = (t) => String(t || "").replace(/[<>&]/g, "");

      function renderMemory() {
        const facts = memory.facts.slice(-30).reverse();
        const turns = memory.turns.slice(-8).reverse();
        const factHtml = facts.length
          ? facts.map((f) => '<div style="margin:3px 0">· ' + esc(f.text) + ' <span style="opacity:.45;font-size:11px">' + fmtTime(f.at) + '</span></div>').join("")
          : '<div style="opacity:.6">还没记住什么</div>';
        const turnHtml = turns.length
          ? turns.map((t) => '<div style="margin:6px 0;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.04)">' +
              '<div style="opacity:.65">你：' + esc(t.user || "") + '</div>' +
              '<div>它：' + esc(t.pet || "（没回）") + '</div></div>').join("")
          : '<div style="opacity:.6">还没有对话</div>';
        memEl.innerHTML =
          '<div style="font-weight:600;margin-bottom:6px">它记得什么</div>' +
          '<div style="opacity:.7;margin-bottom:8px">情绪 ' + moodLabel() + '(' + Math.round(core.mood) + ') · 亲密 ' + Math.round(core.intimacy) + '</div>' +
          '<div style="font-weight:600;margin:8px 0 4px">记住的事（' + memory.facts.length + '）</div>' + factHtml +
          '<div style="font-weight:600;margin:12px 0 4px">最近的对话</div>' + turnHtml +
          '<div style="display:flex;gap:8px;margin-top:12px">' +
          '<button id="mem-clear" style="flex:1;padding:8px;border-radius:10px;border:1px solid #5a2b33;background:#2a1620;color:#ffb4bd">清空记忆</button>' +
          '<button id="mem-close" style="flex:1;padding:8px;border-radius:10px;border:1px solid #33415c;background:transparent;color:#dbe4f7">关闭</button>' +
          '</div>';
        memEl.querySelector("#mem-close").addEventListener("click", () => { memEl.style.display = "none"; });
        memEl.querySelector("#mem-clear").addEventListener("click", () => {
          if (!window.confirm("清空它记住的事和最近对话？")) return;
          memory.turns = [];
          memory.facts = [];
          saveMemory();
          renderMemory();
        });
      }

      function openMemory() { renderMemory(); memEl.style.display = "block"; }

      // ── 提醒（方案 B：自定义时间 + 文案） ──
      const REMIND_KEY = "pet-overlay.reminders";
      const remindEl = document.createElement("div");
      remindEl.id = "pet-overlay-remind";
      remindEl.style.cssText = "position:fixed;left:12px;right:12px;bottom:90px;max-height:60vh;overflow-y:auto;" +
        "background:rgba(22,28,42,.98);color:#dbe4f7;border:1px solid rgba(120,150,220,.3);border-radius:14px;" +
        "padding:12px;z-index:2147483006;display:none;font:14px/1.5 system-ui,-apple-system,sans-serif";
      document.body.appendChild(remindEl);

      function loadReminders() {
        try { return JSON.parse(localStorage.getItem(REMIND_KEY) || "[]"); } catch { return []; }
      }
      function saveReminders(list) {
        try { localStorage.setItem(REMIND_KEY, JSON.stringify(list)); } catch { /* ignore */ }
      }

      function renderReminders() {
        const list = loadReminders();
        const rows = list.length
          ? list.map((r, i) => '<div style="display:flex;gap:8px;align-items:center;margin:4px 0">' +
              '<span style="font-variant-numeric:tabular-nums">' + r.t + '</span>' +
              '<span style="flex:1">' + r.text.replace(/[<>&]/g, "") + '</span>' +
              '<button data-del="' + i + '" style="padding:4px 10px;border-radius:8px;border:0;background:#3a2430;color:#ffd9d9">删</button>' +
              '</div>').join("")
          : '<div style="opacity:.6">还没有提醒</div>';
        remindEl.innerHTML =
          '<div style="font-weight:600;margin-bottom:8px">提醒（每天重复）</div>' + rows +
          '<div style="display:flex;gap:6px;margin-top:10px">' +
          '<input id="rm-time" type="time" value="09:00" style="width:110px;padding:6px;border-radius:8px;border:1px solid #33415c;background:#111827;color:#dbe4f7">' +
          '<input id="rm-text" placeholder="提醒什么" style="flex:1;padding:6px;border-radius:8px;border:1px solid #33415c;background:#111827;color:#dbe4f7">' +
          '</div>' +
          '<div style="display:flex;gap:8px;margin-top:10px">' +
          '<button id="rm-add" style="flex:1;padding:8px;border-radius:10px;border:0;background:#2b4a8a;color:#fff">添加</button>' +
          '<button id="rm-close" style="flex:1;padding:8px;border-radius:10px;border:1px solid #33415c;background:transparent;color:#dbe4f7">关闭</button>' +
          '</div>';
        remindEl.querySelectorAll("[data-del]").forEach((b) => {
          b.addEventListener("click", () => {
            const list2 = loadReminders();
            list2.splice(Number(b.getAttribute("data-del")), 1);
            saveReminders(list2);
            renderReminders();
          });
        });
        remindEl.querySelector("#rm-add").addEventListener("click", () => {
          const t = remindEl.querySelector("#rm-time").value || "09:00";
          const text = (remindEl.querySelector("#rm-text").value || "").trim();
          if (!text) return;
          const list2 = loadReminders();
          list2.push({ t, text });
          saveReminders(list2);
          renderReminders();
        });
        remindEl.querySelector("#rm-close").addEventListener("click", () => { remindEl.style.display = "none"; });
      }

      function openReminders() {
        renderReminders();
        remindEl.style.display = "block";
      }

      function remindersTick() {
        const list = loadReminders();
        if (!list.length || quiet || pet.asleep) return;
        const now = new Date();
        const hm = String(now.getHours()).padStart(2, "0") + ":" + String(now.getMinutes()).padStart(2, "0");
        const day = now.toISOString().slice(0, 10);
        for (const r of list) {
          if (r.t !== hm) continue;
          const key = "pet-overlay.remDone." + day + "." + r.t + "." + r.text;
          try { if (localStorage.getItem(key) === "1") continue; } catch { /* ignore */ }
          try { localStorage.setItem(key, "1"); } catch { /* ignore */ }
          showBubble("⏰ " + r.text);
          try { showAct("pace"); } catch { /* ignore */ }
          break;
        }
      }

      const panel = document.createElement("div");
      panel.id = "pet-overlay-panel";
      panel.innerHTML =
        '<div class="po-row"><span>名字</span><input id="po-name" maxlength="12" /></div>' +
        '<div class="po-row"><span>叫我</span><input id="po-call" maxlength="12" /></div>' +
        '<div class="po-row"><span>语气</span><select id="po-tone">' +
        '<option value="soft">软萌</option><option value="blunt">直爽</option><option value="cool">冷淡</option>' +
        '</select></div>' +
        '<div class="po-actions"><button id="po-save">保存</button><button id="po-close" class="ghost">关闭</button></div>' +
        '<div class="po-diag" id="po-diag"></div>';
      document.body.appendChild(panel);

      // 真素材：webm 透明动画，构建时以 data URL 内联（宿主只提供 png/webp/svg）
      // >>>ASSETS（由 scripts/embed-assets.mjs 生成，勿手改）
      const ASSETS = {
        "brush": "data:video/webm;base64,",
        "cheer": "data:video/webm;base64,",
        "click-happy": "data:video/webm;base64,",
        "click-shy": "data:video/webm;base64,",
        "click-tickle": "data:video/webm;base64,",
        "click-tsun": "data:video/webm;base64,",
        "click-wave": "data:video/webm;base64,",
        "happy": "data:video/webm;base64,",
        "idle": "data:video/webm;base64,",
        "look": "data:video/webm;base64,",
        "sleep-end": "data:video/webm;base64,",
        "sleep-start": "data:video/webm;base64,",
        "sleep": "data:video/webm;base64,",
        "think": "data:video/webm;base64,",
        "walk": "data:video/webm;base64,",
      };
      // <<<ASSETS
      // 预加载全部动画：切换只改显隐，不重载资源，避免闪屏
      const stage = document.createElement("div");
      stage.style.cssText = "position:fixed;pointer-events:none;z-index:2147482999;display:none";
      document.body.appendChild(stage);

      const ANIM_RATE = 1.0; // 原速；改速率必须同时改 CLIP_MS，否则会截断/慢放 // 素材帧率高，放慢一点更像活着
      // 文件头写的 10042ms 是容器声明的循环长度；实际画面只有约 5.3 秒
      // （最后簇时间戳 5333ms），按 10 秒播会有 4.7 秒定格，所以以实际画面为准
      const TRIM_START = 0.6; // 跳过每段开头的"看/收势"
      const TRIM_END = 0.6;   // 跳过结尾的收势
      const CLIP_MS = 6400; // 原速下画面约 6.4 秒（5333 + 最后一簇）
      const vids = {};
      const blobCache = {};
      let animName = "";
      let animOk = false;

      function toBlobUrl(name, dataUrl) {
        if (blobCache[name]) return blobCache[name];
        const comma = dataUrl.indexOf(",");
        const bin = atob(dataUrl.slice(comma + 1));
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
        const url = URL.createObjectURL(new Blob([bytes], { type: "video/webm" }));
        blobCache[name] = url;
        return url;
      }

      // 素材服务：优先从本机 8766 按需拉取；服务不在就回退到内联的那几段
      const ASSET_BASE = "http://127.0.0.1:8766/";
      const ANIM_FILES = {
        idle: "待机呼吸休闲",
        look: "东张西望",
        happy: "开心小跑",
        think: "工作状态-思考冒泡",
        sleep: "睡觉-循环",
        sleepStart: "sleep-start",
        sleepEnd: "sleep-end",
        walk: "侧身急躁跑",
        clickHappy: "click-happy",
        clickShy: "click-shy",
        clickTickle: "click-tickle",
        clickTsun: "click-tsun",
        clickWave: "click-wave",
        yawn: "哈欠连天",
        busy: "工作状态-忙碌点按",
        code: "写代码",
        archive: "工作状态-清点归档",
        pace: "工作状态-原地踱步张望",
        record: "轻快记录",
        cat: "撸猫",
        mirror: "照镜子",
        swing: "荡秋千",
        juggle: "三球抛接",
        rubik: "原地专心玩魔方",
        toycar: "原地蹲下玩玩具汽车",
        dance: "优雅女仆舞",
        sway: "轻快摇摆舞",
        float: "原地漂浮踏步",
        icecream: "吃冰淇淋融化",
        watergun: "玩水枪",
        startled: "打瞌睡被惊醒",

        nap: "原地小憩沉眠",
        horseride: "骑木马",
        shuttle: "踢毽子",
        top: "抽陀螺",
        kite: "放风筝",
        balloon: "吹气球",
        gift: "拆礼物",
        fan: "摇扇纳凉",
        gomoku: "下五子棋",
        poker: "扑克魔术",
        curtsy: "女仆屈膝礼仪",
        dressup: "整体换装试色",
        brush: "brush",
        whale: "蓝鲸现世",
        ghost: "萌化小幽灵",
        animals: "动物环绕",
        flowers: "蝴蝶蜜蜂环绕头顶开花",
        dove: "变鸽子",
        bloom: "凭空生花",
        kawaiiDance: "可爱宅舞",
        violin: "小提琴演奏",
        flute: "吹笛子",
        spin: "小幅度原地360度旋转展示",
        mooncake: "中秋赏月吃月饼",
        xmas: "装点圣诞树",
        redpacket: "收红包",
        fireworks: "放烟花",
        lantern: "放孔明灯",
        riverLantern: "放河灯",
        snowman: "堆雪人",
        halloween: "讨糖南瓜灯",
        chrysanthemum: "插茱萸赏菊",
        qixi: "穿针乞巧",
        lion: "舞狮头",
        fu: "写福字",
        mealBreakfast: "吃早餐",
        mealLunch: "吃午餐",
        mealDinner: "吃晚餐",
        mealHotpot: "涮火锅",
        mealWatermelon: "吃西瓜",
        stretch: "超大伸懒腰",
        hum: "悠闲哼歌",
        bubble: "鲸鱼吐泡泡特效",
        sad: "工作状态-垂头叹气冒汗",
        cheer: "cheer",
      };
      let remoteNames = new Set();

      async function loadRemoteList() {
        try {
          const res = await fetch(ASSET_BASE + "list.json", { cache: "no-store" });
          const data = await res.json();
          remoteNames = new Set((data.files || []).map((f) => String(f).replace(/\.webm$/i, "")));
          diag.vid = "remote:" + remoteNames.size;
        } catch {
          remoteNames = new Set();
          diag.vid = "remote:off";
        }
      }

      function videoFor(name) {
        if (vids[name]) return vids[name];
        const file = ANIM_FILES[name] || name;
        let src = null;
        if (remoteNames.has(file)) src = ASSET_BASE + "a/" + encodeURIComponent(file) + ".webm";
        else if (ASSETS[file]) src = toBlobUrl(file, ASSETS[file]); // 内联键就是文件名
        else if (ASSETS[name]) src = toBlobUrl(name, ASSETS[name]);
        if (!src) return null;

        const v = document.createElement("video");
        v.muted = true;
        v.loop = true;
        v.playsInline = true;
        v.setAttribute("playsinline", "");
        v.preload = "auto";
        v.playbackRate = ANIM_RATE;
        v.style.cssText = "position:absolute;inset:0;width:100%;height:100%;object-fit:contain;opacity:0;transition:opacity .2s ease";
        v.addEventListener("error", () => {
          diag.vid = "err:" + file;
          try { delete vids[name]; v.remove(); } catch { /* ignore */ } // 下次重建，避免一直用坏元素
        });
        v.src = src;
        v.play().catch(() => {});
        stage.appendChild(v);
        vids[name] = v;
        return v;
      }

      // ── 播放层 ──
      // 切换只改 opacity；旧画面在 transitionend 里暂停（执行时比对 animName），不用延迟定时器。
      function pauseIfStale(el, key) {
        const onDone = () => {
          el.removeEventListener("transitionend", onDone);
          if (key !== animName) { try { el.pause(); } catch { /* ignore */ } }
        };
        el.addEventListener("transitionend", onDone);
      }

      function showVideo(name, ms) {
        const target = vids[name];
        if (!target) { animOk = false; stage.style.display = "none"; return false; }
        const dur = ms || 300;
        const prev = animName;
        animName = name;
        animOk = true;
        stage.style.display = "block";

        for (const [k, el] of Object.entries(vids)) {
          if (k === name) continue;
          if (k === prev) {
            // 上一段：淡出，稍后暂停
            el.style.transition = "opacity " + dur + "ms ease";
            el.style.opacity = "0";
            continue;
          }
          // 其它：立即暂停，别在后台空转（卡顿主因）
          el.style.opacity = "0";
          try { el.pause(); } catch { /* ignore */ }
        }

        // 把目标提到最上层：视频按 DOM 顺序层叠，切回早先创建的元素会被盖住
        try { if (target.parentElement && target.parentElement.lastElementChild !== target) stage.appendChild(target); } catch { /* ignore */ }
        // 提到最上层：视频按 DOM 顺序叠放，后创建的在上面，切回旧元素会被盖住
        try { if (target.parentElement && target.parentElement.lastElementChild !== target) stage.appendChild(target); } catch { /* ignore */ }
        target.style.transition = "opacity " + dur + "ms ease";
        target.style.opacity = "1";
        target.playbackRate = ANIM_RATE;
        try {
          if (target.ended || (isFinite(target.duration) && target.currentTime >= target.duration - 0.05)) target.currentTime = 0;
        } catch { /* ignore */ }
        target.loop = true;
        target.play().catch(() => {});

        if (prev && prev !== name) {
          const pv = vids[prev];
          setTimeout(() => {
            if (!pv) return;
            if (animName === prev) return; // 又切回来了
            try { pv.pause(); } catch { /* ignore */ }
          }, dur + 80);
        }
        return true;
      }

      function fadeTo(name, ms) {
        logTrace("fade:" + name);
        const v = videoFor(name);
        if (!v) return;
        showVideo(name, ms);
      }

      function setAnim(name) {
        if (animName === name) return;
        const v = videoFor(name);
        if (!v) { animOk = false; stage.style.display = "none"; return; }
        if (v.readyState >= 2 || animName === "") { showVideo(name); return; }
        v.addEventListener("loadeddata", () => { if (animName === name) showVideo(name); }, { once: true });
      }

      const bubble = document.createElement("div");
      bubble.id = "pet-overlay-bubble";
      document.body.appendChild(bubble);

      const ctx2d = canvas.getContext("2d");
      const pet = {
        x: 0, y: 0, baseY: 0, targetX: 0, flip: 1,
        bob: 0, pop: 0, squash: 1, dragging: false, vy: 0,
        mode: "idle", nextDecision: 0, scale: 1, lookFor: 0, animLock: 0, asleep: false,
      };

      const W = () => canvas.clientWidth;
      const H = () => canvas.clientHeight;

      function resize() {
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        canvas.width = Math.floor(W() * dpr);
        canvas.height = Math.floor(H() * dpr);
        ctx2d.setTransform(dpr, 0, 0, dpr, 0, 0);
        pet.baseY = H() * 0.78;
        if (!pet.x) { pet.x = W() * 0.5; pet.targetX = pet.x; }
        pet.y = Math.min(pet.y || pet.baseY, pet.baseY);
      }
      window.addEventListener("resize", resize);

      function hideBubble() {
        clearTimeout(showBubble.t);
        bubble.classList.remove("show");
        pet.hold = false;
      }

      function showBubble(text) {
        if (quiet) return; // 安静模式：只做动作，不说话
        const body = String(text || "");
        bubble.textContent = body;
        bubble.classList.add("show");
        clearTimeout(showBubble.t);
        // 说话期间站住不动，气泡跟着走会读不清
        pet.hold = true;
        if (pet.mode === "walk") pet.mode = "idle";
        const hold = Math.min(30000, 3000 + body.length * 200);
        showBubble.t = setTimeout(hideBubble, hold);
      }

      // 单击不再关闭（会误触），双击才收起
      bubble.addEventListener("pointerdown", (e) => e.stopPropagation(), { capture: true });
      bubble.addEventListener("dblclick", () => hideBubble());

      function placeSayBar() {
        const vw = window.innerWidth || 360;
        const w = sayBar.offsetWidth || 240;
        const half = w / 2 + 8;
        const left = Math.max(half, Math.min(vw - half, pet.x));
        sayBar.style.left = Math.round(left) + "px";
        sayBar.style.top = Math.max(72, Math.round(pet.y - HIT_H * 0.95 - 12)) + "px";
      }

      function openSayBar() {
        sayBar.classList.add("open");
        placeSayBar();
        // 不自动聚焦：自动弹键盘会把输入条顶到键盘下面，看起来像"点了没反应"
      }

      function closeSayBar() {
        sayBar.classList.remove("open");
        sayInput.blur();
      }

      async function submitSay() {
        const text = String(sayInput.value || "").trim();
        if (!text) { showBubble("先打点字…"); return; }
        if (sayBtn.disabled) return;
        sayBtn.disabled = true;
        showBubble("……");
        try {
          touch();
          if (pet.asleep) wakeUp();
          settleUser(text);
          startWorking();
          const res = await say(ctx, text);
          if (res && res.ok) {
            sayInput.value = "";
            closeSayBar();
            showBubble("说给你了…");
          } else {
            showBubble("没送出去：" + ((res && res.reason) || "未知原因"));
            stopWorking("sad"); // 发送失败 = 出错档（垂头叹气）
          }
        } catch (err) {
          const msg = String((err && err.message) || err || "");
          if (msg.includes("inactive context")) {
            showBubble("还没连上，等几秒再试。");
            stopWorking(null);
          } else {
            showBubble("出错：" + ((err && err.name) || "Error") + "：" + msg);
          }
        } finally {
          sayBtn.disabled = false;
        }
      }

      window.addEventListener("pointerdown", (e) => {
        if (sayBar.classList.contains("open")) {
          if (!sayBar.contains(e.target) && !hit.contains(e.target)) closeSayBar();
        }
        if (menu.classList.contains("open")) {
          if (!menu.contains(e.target) && !hit.contains(e.target)) closeMenu();
        }
      }, { capture: true, passive: true });

      sayBar.addEventListener("pointerdown", (e) => e.stopPropagation(), { capture: true });
      function fillPanel() {
        const nameEl = document.getElementById("po-name");
        const callEl = document.getElementById("po-call");
        const toneEl = document.getElementById("po-tone");
        const diagEl = document.getElementById("po-diag");
        if (nameEl) nameEl.value = persona.name;
        if (callEl) callEl.value = persona.callYou;
        if (toneEl) toneEl.value = persona.tone;
        const st = stageOf(core.intimacy);
        if (diagEl) {
          diagEl.textContent =
            "构建 1121-1106 · " +
            "情绪 " + moodLabel() + "(" + Math.round(core.mood) + ")" +
            " · 亲密 " + Math.round(core.intimacy) + "(" + st.name + ")" +
            "\n记忆 " + memory.turns.length + " 轮 · " + memory.facts.length + " 条" +
            "\n" +
            "会话 " + diag.sid + " · " + diag.via +
            "\n本地 " + diag.local + " · 轮次 " + diag.turns +
            "\n远程 " + diag.remote + " · 轮询 " + diag.polls +
            "\n视频 " + diag.vid + " ok=" + animOk + " mode=" + pet.mode +
            "\n气泡 " + (diag.bub || "-") +
            "\n字段 " + (diag.keys || "-") +
            "\n错误 " + (diag.err || "-") +
            "\n工作 " + diag.work + " | " + (diag.chk || "-") +
            "\n待机 " + diag.idle +
            "\n轨迹\n" + (trace.slice(-6).join("\n") || "-");
        }
      }

      function openMenu() {
        syncQuietLabel();
        menu.classList.add("open");
        const vw = window.innerWidth || 360;
        const mw = menu.offsetWidth || 180;
        let left = pet.x + 40;
        if (left + mw > vw - 8) left = pet.x - mw - 40;
        menu.style.left = Math.max(8, Math.round(left)) + "px";
        menu.style.top = Math.max(72, Math.round(pet.y - HIT_H * 0.7)) + "px";
      }

      function closeMenu() { menu.classList.remove("open"); }

      const pmQuiet = document.getElementById("pm-quiet");
      const syncQuietLabel = () => {
        if (pmQuiet) pmQuiet.textContent = quiet ? "安静模式：开" : "安静模式：关";
      };
      if (pmQuiet) {
        pmQuiet.addEventListener("click", () => {
          setQuiet(!quiet);
          syncQuietLabel();
          closeMenu();
          if (!quiet) showBubble("我回来啦。");
        });
      }

      const pmTalk = document.getElementById("pm-talk");
      const pmSetting = document.getElementById("pm-setting");
      const pmClose = document.getElementById("pm-close");
      if (pmTalk) pmTalk.addEventListener("click", () => { closeMenu(); openSayBar(); });
      if (pmSetting) pmSetting.addEventListener("click", () => { closeMenu(); openPanel(); });
      const pmSea = document.getElementById("pm-sea");
      if (pmSea) pmSea.addEventListener("click", () => { closeMenu(); openSea(); });
      const pmMemory = document.getElementById("pm-memory");
      if (pmMemory) pmMemory.addEventListener("click", () => { closeMenu(); openMemory(); });
      const pmRemind = document.getElementById("pm-remind");
      if (pmRemind) pmRemind.addEventListener("click", () => { closeMenu(); openReminders(); });
      const pmProTest = document.getElementById("pm-protest");
      if (pmProTest) pmProTest.addEventListener("click", () => { closeMenu(); showBubble(pickProactiveLine()); });
      const pmGreetTest = document.getElementById("pm-greettest");
      if (pmGreetTest) pmGreetTest.addEventListener("click", () => {
        closeMenu();
        const all = [...GREETS.back];
        showBubble(all[Math.floor(Math.random() * all.length)]);
      });
      const pmBubTest = document.getElementById("pm-bubtest");
      if (pmBubTest) pmBubTest.addEventListener("click", () => { closeMenu(); showBubble("气泡测试：如果你看到这句，说明渲染正常。"); });
      const pmAnims = document.getElementById("pm-anims");
      if (pmAnims) pmAnims.addEventListener("click", () => { closeMenu(); openAnimPicker(); });
      if (pmClose) pmClose.addEventListener("click", closeMenu);

      function openPanel() {
        fillPanel();
        panel.classList.add("open");
        panel.style.left = "50%";
        panel.style.top = "22%";
        panel.style.transform = "translateX(-50%)";
      }

      function closePanel() {
        panel.classList.remove("open");
      }

      const poSave = document.getElementById("po-save");
      const poClose = document.getElementById("po-close");
      if (poSave) {
        poSave.addEventListener("click", () => {
          const nameEl = document.getElementById("po-name");
          const callEl = document.getElementById("po-call");
          const toneEl = document.getElementById("po-tone");
          persona.name = (nameEl && nameEl.value.trim()) || "小蓝";
          persona.callYou = (callEl && callEl.value.trim()) || "你";
          persona.tone = (toneEl && toneEl.value) || "soft";
          savePersona();
          closePanel();
          showBubble(persona.name + "：记住啦。");
        });
      }
      if (poClose) poClose.addEventListener("click", closePanel);

      sayBtn.addEventListener("click", submitSay);
      sayBtn.addEventListener("pointerup", (e) => { if (e.pointerType !== "mouse") submitSay(); });
      sayInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter") { e.preventDefault(); submitSay(); }
        if (e.key === "Escape") { e.preventDefault(); closeSayBar(); }
      });

      function placeBubble() {
        bubble.style.left = pet.x + "px";
        bubble.style.top = pet.y - PET_H * pet.scale - 22 + "px";
      }

      function draw(pet2, t) {
        const bodyH = PET_H * 0.52;
        const bodyW = PET_H * 0.62;
        const bob = Math.sin(pet2.bob) * 3;
        const s = pet2.scale * pet2.squash * (1 + pet2.pop * 0.18);

        ctx2d.save();
        ctx2d.translate(pet2.x, pet2.y + bob - pet2.pop * 10);
        ctx2d.scale(pet2.flip * s, s);

        // 影子
        ctx2d.save();
        ctx2d.scale(pet2.flip * s, s);
        ctx2d.globalAlpha = 0.26;
        ctx2d.fillStyle = "#000";
        ctx2d.beginPath();
        ctx2d.ellipse(0, -10, 62, 11, 0, 0, Math.PI * 2);
        ctx2d.fill();
        ctx2d.restore();

        // 尾巴
        const tail = Math.sin(pet2.bob * 1.6) * 0.22;
        ctx2d.save();
        ctx2d.translate(-bodyW * 0.86, -bodyH * 0.52);
        ctx2d.rotate(tail);
        ctx2d.fillStyle = "#2f56d1";
        ctx2d.beginPath();
        ctx2d.moveTo(0, 0);
        ctx2d.quadraticCurveTo(-32, -26, -44, -2);
        ctx2d.quadraticCurveTo(-32, 2, -30, 12);
        ctx2d.quadraticCurveTo(-28, 22, -44, 24);
        ctx2d.quadraticCurveTo(-20, 30, 0, 10);
        ctx2d.closePath();
        ctx2d.fill();
        ctx2d.restore();

        // 身体
        const g = ctx2d.createLinearGradient(0, -bodyH, 0, 0);
        g.addColorStop(0, "#5b7cff");
        g.addColorStop(1, "#3455d4");
        ctx2d.fillStyle = g;
        ctx2d.beginPath();
        ctx2d.ellipse(0, -bodyH * 0.52, bodyW * 0.52, bodyH * 0.58, 0, 0, Math.PI * 2);
        ctx2d.fill();

        // 肚皮
        ctx2d.fillStyle = "rgba(255,255,255,.9)";
        ctx2d.beginPath();
        ctx2d.ellipse(bodyW * 0.02, -bodyH * 0.36, bodyW * 0.32, bodyH * 0.34, 0, 0, Math.PI * 2);
        ctx2d.fill();

        // 背鳍
        ctx2d.fillStyle = "#2a4ac0";
        ctx2d.beginPath();
        ctx2d.moveTo(-6, -bodyH * 1.02);
        ctx2d.quadraticCurveTo(10, -bodyH * 1.24, 26, -bodyH * 1.0);
        ctx2d.closePath();
        ctx2d.fill();

        // 眼睛
        const blink = t % 4200 < 130 ? 0.12 : 1;
        const eyeY = -bodyH * 0.66;
        const eyeX = bodyW * 0.18;
        ctx2d.fillStyle = "#10131a";
        for (const dx of [-eyeX * 0.72, eyeX * 0.72]) {
          ctx2d.save();
          ctx2d.translate(dx, eyeY);
          ctx2d.scale(1, blink);
          ctx2d.beginPath();
          ctx2d.arc(0, 0, 5, 0, Math.PI * 2);
          ctx2d.fill();
          ctx2d.restore();
        }

        // 嘴
        ctx2d.strokeStyle = "#10131a";
        ctx2d.lineWidth = 2;
        ctx2d.lineCap = "round";
        ctx2d.beginPath();
        ctx2d.arc(0, eyeY + 14, 6, 0.15 * Math.PI, 0.85 * Math.PI);
        ctx2d.stroke();

        ctx2d.restore();
      }

      // 待机播放器：单个循环，每段演满 CLIP_MS 就接下一段，不再嵌套定时器
      const IDLE_ACTS = ["look", "yawn", "stretch", "hum", "bubble"];
      let lastIdleAct = "";
      let idleGen = 0;      // 互动时 +1，循环据此让位
      let idleBusy = false; // 防止重复起循环

      function pickIdleAct() {
        decayMood(Date.now());
        const fests = todayFestivals();
        if (fests.length && Math.random() < 0.4) {
          const freshF = fests.filter((n) => n !== lastIdleAct);
          const pickF = (freshF.length ? freshF : fests)[Math.floor(Math.random() * (freshF.length || fests.length))];
          lastIdleAct = pickF;
          return pickF;
        }
        const hour = new Date().getHours();
        const night = hour >= 23 || hour < 7;
        let pool;
        if (core.mood <= -15) pool = ["sad", "yawn", "nap"];
        else if (core.mood >= 15) pool = ["cheer", "bubble", "dance", "sway", "juggle", "cat"];
        else if (night) pool = [
          "yawn", "nap", "float", "startled", "mirror",
          "cat", "brush", "gomoku", "rubik", "stretch", "bubble", "toycar", "brush",
        ];
        else pool = [
          "bubble", "stretch", "yawn", "cat", "mirror", "swing",
          "juggle", "rubik", "toycar", "icecream", "watergun", "float",
          "mealBreakfast", "mealLunch", "mealWatermelon", "mealDinner", "mealHotpot",
          "horseride", "shuttle", "top", "kite", "balloon", "gift", "fan",
          "gomoku", "poker", "curtsy", "dressup", "brush", "whale", "ghost",
          "animals", "flowers", "dove", "bloom", "kawaiiDance", "violin", "flute", "spin",
        ];
        const fresh = pool.filter((n) => n !== lastIdleAct);
        const list = fresh.length ? fresh : pool;
        const pick = list[Math.floor(Math.random() * list.length)];
        lastIdleAct = pick;
        return pick;
      }

      function showAct(name) {
        const v = videoFor(name);
        if (!v || v.readyState < 2) { logTrace("skip:" + name); return false; }
        // 同一段正在播就不要重置进度，否则会被反复从头播（表现为一直循环）
        if (animName === name && !v.ended && !v.paused) {
          v.style.opacity = "1";
          return true;
        }
        logTrace("act:" + name);
        v.loop = true;
        try { v.currentTime = 0; } catch { /* 未就绪 */ }
        v.playbackRate = ANIM_RATE;
        v.play().catch(() => {});
        showVideo(name, 500);
        return true;
      }

      // ── 工作联动 ──
      const WORK_ACTS = ["think", "busy", "archive", "pace"]; // 对应 thinking/working/result/waiting
      let workGen = 0;        // 每次开始/结束 +1，旧的轮换自动作废
      let workRotation = null;
      let workTimeout = null;
      let workPoll = null;
      let working = false;
      let workBaseTurns = 0;

      let replySeq = 0;      // 每收到一条回复 +1
      let workBaseReply = 0; // 进入工作状态时的回复序号

      function startWorking() {
        workGen += 1;
        working = true;
        workBaseTurns = diag.turns;
        workBaseReply = replySeq;
        if (workTimeout) clearTimeout(workTimeout);
        workTimeout = setTimeout(() => { if (working) stopWorking(null); }, 90000); // 90 秒兜底
        if (workPoll) clearInterval(workPoll);
        workPoll = setInterval(() => {
          if (!working) { clearInterval(workPoll); workPoll = null; return; }
          diag.chk = "reply=" + replySeq + " base=" + workBaseReply;
          if (replySeq > workBaseReply) stopWorking("cheer");
        }, 1000);
        diag.work = "start gen=" + workGen + " base=" + workBaseTurns;
        const gen = workGen;
        idleGen += 1; // 停掉待机循环
        idleBusy = false;
        pet.mode = "idle";
        pet.animLock = performance.now() + 3600 * 1000;
        let step = 0;
        const playWork = (name) => {
          const v = videoFor(name);
          if (!v) return false;
          if (v.readyState >= 2) return showAct(name);
          // 未解码好：等它就绪立刻播，别让待机动作继续演
          v.addEventListener("canplay", () => { if (gen === workGen) showAct(name); }, { once: true });
          return false;
        };
        const rotate = () => {
          if (gen !== workGen) return;
          const name = WORK_ACTS[step % WORK_ACTS.length];
          step += 1;
          if (playWork(name)) diag.idle = "work:" + step + " " + name;
          workRotation = setTimeout(rotate, 6000);
        };
        rotate();
      }

      function stopWorking(reaction) {
        try { stopWorkingInner(reaction); } catch (err) {
          diag.work = "err:" + ((err && err.name) || "?");
          working = false;
          pet.animLock = 0;
          try { fadeTo("idle", 400); } catch { /* ignore */ }
          idleBusy = false;
          try { idleLoop(); } catch { /* ignore */ }
        }
      }

      function stopWorkingInner(reaction) {
        working = false;
        if (workTimeout) { clearTimeout(workTimeout); workTimeout = null; }
        if (workPoll) { clearInterval(workPoll); workPoll = null; }
        const gen0 = workGen + 1;
        const rv0 = reaction ? videoFor(reaction) : null;
        diag.work = "stop " + (reaction || "-") + " rs=" + (rv0 ? rv0.readyState : "no") + " gen=" + workGen;
        workGen += 1;
        if (workRotation) { clearTimeout(workRotation); workRotation = null; }
        pet.animLock = 0;
        const rv = reaction ? videoFor(reaction) : null;
        if (reaction && rv && rv.readyState < 2) {
          // 还没解码好：等它，别急着把待机循环开起来（否则会把雀跃盖掉）
          rv.addEventListener("canplay", () => {
            if (workGen !== gen0) return;
            if (showAct(reaction)) {
              pet.animLock = performance.now() + 4000;
              setTimeout(() => {
                pet.animLock = 0;
                fadeTo("idle", 500);
                idleBusy = false;
                idleLoop();
              }, 4000);
            }
          }, { once: true });
          return;
        }
        if (reaction && rv && rv.readyState >= 2 && showAct(reaction)) {
          diag.work = "played " + reaction;
          pet.animLock = performance.now() + 4000;
          setTimeout(() => {
            pet.animLock = 0;
            fadeTo("idle", 500);
            idleBusy = false;
            idleLoop();
          }, 4000);
          return;
        }
        fadeTo("idle", 500);
        idleBusy = false;
        idleLoop();
      }

      // ── 节日（按日期，一年一次） ──
      const FESTIVALS = [
        { lunar: [8, 15], anim: "mooncake", line: "中秋了，吃月饼吗？" },
        { lunar: [7, 7], anim: "qixi", line: "今天是七夕呢。" },
        { lunar: [9, 9], anim: "chrysanthemum", line: "重阳了，去看看菊花？" },
        { lunar: [1, 1], anim: "fu", line: "新年快乐！" },
        { lunar: [1, 1], anim: "fireworks", line: "过年啦！" },
        { lunar: [1, 1], anim: "redpacket", line: "红包拿来～" },
        { lunar: [1, 1], anim: "lion", line: "舞狮啦！" },
        { solar: [12, 25], anim: "xmas", line: "圣诞快乐！" },
        { solar: [10, 31], anim: "halloween", line: "不给糖就捣蛋。" },
        { solar: [1, 1], anim: "gift", line: "新年第一天，拆个礼物？" },
      ];

      function lunarMonthDay() {
        try {
          const f = new Intl.DateTimeFormat("zh-CN-u-ca-chinese", { month: "numeric", day: "numeric" });
          const parts = f.formatToParts(new Date());
          const m = parts.find((x) => x.type === "month");
          const d = parts.find((x) => x.type === "day");
          return m && d ? [Number(m.value), Number(d.value)] : null;
        } catch {
          return null;
        }
      }

      let festCache = { day: "", list: [] };

      /** 当天所有节日动作（可能多个，比如春节），缓存到跨天 */
      function todayFestivals() {
        const day = new Date().toISOString().slice(0, 10);
        if (festCache.day === day) return festCache.list;
        const now = new Date();
        const solar = [now.getMonth() + 1, now.getDate()];
        const lunar = lunarMonthDay();
        const list = FESTIVALS.filter((f) => {
          if (f.solar) return f.solar[0] === solar[0] && f.solar[1] === solar[1];
          if (f.lunar && lunar) return f.lunar[0] === lunar[0] && f.lunar[1] === lunar[1];
          return false;
        }).map((f) => f.anim);
        festCache = { day, list };
        return list;
      }

      // ── 主动开口 ──
      const PROACTIVE = {
        lonely: ["你在忙吗？", "好久没说话了。", "陪我说句话嘛。"],
        remind: ["记得喝水。", "坐久了，起来动一动？", "眼睛累了吧，歇一下。"],
        bored: ["好无聊啊……", "没事干，要不要摸鱼？", "我在这儿发呆呢。"],
        cheer: ["加油！", "别急，慢慢来。", "我陪着你呢。"],
      };
      const PROACTIVE_MAX_PER_DAY = 10;
      let proactiveDay = "";
      let proactiveCount = 0;

      function proactiveDue() {
        const now = new Date();
        const h = now.getHours();
        if (h < 7 || h >= 23) return false;      // 深夜不打扰
        if (quiet || pet.asleep) return false;
        if (Date.now() - lastActive < 20 * 60 * 1000) return false; // 20 分钟内有互动
        const day = now.toISOString().slice(0, 10);
        if (proactiveDay !== day) { proactiveDay = day; proactiveCount = 0; }
        return proactiveCount < PROACTIVE_MAX_PER_DAY;
      }

      function pickProactiveLine() {
        const mood = core.mood;
        let pool;
        if (mood <= -15) pool = [...PROACTIVE.remind, ...PROACTIVE.cheer];
        else if (mood >= 15) pool = [...PROACTIVE.lonely, ...PROACTIVE.bored];
        else pool = [...PROACTIVE.lonely, ...PROACTIVE.bored, ...PROACTIVE.remind];
        return pool[Math.floor(Math.random() * pool.length)];
      }

      async function maybeProactive() {
        if (!proactiveDue()) return;
        let line = "";
        // 内容接口：外部可提供 window.__petOverlay.proactiveSource(ctx) → string
        const src = window.__petOverlay && window.__petOverlay.proactiveSource;
        if (typeof src === "function") {
          try { line = String((await src({ mood: core.mood, intimacy: core.intimacy })) || "").trim(); } catch { line = ""; }
        }
        if (!line) line = pickProactiveLine();
        if (!line) return;
        proactiveCount += 1;
        showBubble(line);
      }

      function setupProactive() {
        setInterval(maybeProactive, 60 * 1000);
      }

      // ── 情境感知：问候 / 回来 / 深夜 ──
      const GREETS = {
        back: ["你回来啦。", "刚刚去哪了？", "等你好久了。"],
      };
      let hiddenAt = 0;

      function dayKey() {
        return new Date().toISOString().slice(0, 10);
      }

      function greetOnce(slot, pool) {
        const key = "pet-overlay.greet." + slot + "." + dayKey();
        try { if (localStorage.getItem(key) === "1") return; } catch { /* ignore */ }
        try { localStorage.setItem(key, "1"); } catch { /* ignore */ }
        const line = pool[Math.floor(Math.random() * pool.length)];
        setTimeout(() => { if (!quiet && !pet.asleep) showBubble(line); }, 1200);
      }

      function contextTick() {
        // 早晚问候已按需求移除，只保留「离开又回来」
      }

      function setupContext() {
        contextTick();
        setInterval(contextTick, 5 * 60 * 1000);
        document.addEventListener("visibilitychange", () => {
          if (document.hidden) { hiddenAt = Date.now(); return; }
          const away = hiddenAt ? Date.now() - hiddenAt : 0;
          hiddenAt = 0;
          if (away > 20 * 60 * 1000) greetOnce("back" + Date.now(), GREETS.back);
        });
      }

      // ── 睡觉 / 醒来 ──
      let lastActive = Date.now();
      const touch = () => { lastActive = Date.now(); };

      function shouldSleep() {
        if (pet.asleep) return true;
        const h = new Date().getHours();
        const night = h >= 23 || h < 7;
        const idleMin = (Date.now() - lastActive) / 60000;
        return night ? idleMin >= 3 : idleMin >= 15;
      }

      function sleepLoop() {
        animName = "sleep";
        animOk = true;
        const v = videoFor("sleep");
        if (v) {
          v.loop = true;
          v.playbackRate = ANIM_RATE;
          v.play().catch(() => {});
          fadeTo("sleep", 500);
        }
        pet.animLock = performance.now() + 30 * 60 * 1000;
        const check = () => {
          if (!pet.asleep) return;
          if (!shouldSleep()) { wakeUp(); return; }
          setTimeout(check, 60000);
        };
        setTimeout(check, 60000);
      }

      /** 睡前：先演「睡觉-开始」（躺下），再进循环 */
      function doSleep(quiet) {
        const start = videoFor("sleepStart");
        if (!start) { sleepLoop(); return; }
        start.loop = false;
        try { start.currentTime = 0; } catch { /* 未就绪 */ }
        start.playbackRate = ANIM_RATE;
        start.play().catch(() => {});
        showVideo("sleepStart", 500);
        pet.animLock = performance.now() + 30000;
        const t0 = performance.now();
        const waitStart = () => {
          if (!pet.asleep) return;
          if (!start.ended && performance.now() - t0 < 14000) { setTimeout(waitStart, 120); return; }
          sleepLoop();
        };
        waitStart();
      }

      function sleepNow() {
        if (pet.asleep) return;
        pet.asleep = true;
        idleGen += 1; // 停掉待机循环

        const h = new Date().getHours();
        const night = h >= 23 || h < 7;
        // 「睡觉-开始」里已经含打哈欠，不再单独演
        if (night) showBubble("夜深了，该睡觉了…");
        doSleep(!night ? false : true);
      }

      function wakeUp() {
        if (!pet.asleep) return;
        pet.asleep = false;
        touch();
        pet.animLock = 0;
        const v = videoFor("sleepEnd");
        const playWake = () => {
          v.loop = false;
          try { v.currentTime = 0; } catch { /* ignore */ }
          v.playbackRate = ANIM_RATE;
          v.play().catch(() => {});
          fadeTo("sleepEnd", 300);
          pet.animLock = performance.now() + CLIP_MS + 600;
          setTimeout(() => {
            pet.animLock = 0;
            fadeTo("idle", 500);
            idleBusy = false;
            idleLoop();
          }, CLIP_MS);
        };
        if (v && v.readyState >= 2) {
          playWake();
        } else if (v) {
          // 素材还没解码：等它，别一闪就回待机
          const t = setTimeout(() => { fadeTo("idle", 400); idleBusy = false; idleLoop(); }, 1500);
          v.addEventListener("canplay", () => { clearTimeout(t); playWake(); }, { once: true });
        } else {
          fadeTo("idle", 500);
          idleBusy = false;
          idleLoop();
        }
      }

      let chainLeft = 0; // 本串还剩几个动作

      function idleLoop() {
        if (idleBusy) return;
        idleBusy = true;
        const gen = idleGen;
        chainLeft = 3 + Math.floor(Math.random() * 3); // 每串 3–5 个

        const step = () => {
          if (gen !== idleGen) { idleBusy = false; return; }      // 被互动打断
          if (pet.animLock) { setTimeout(step, 1200); return; }  // 等互动结束
          if (shouldSleep()) { sleepNow(); return; }
          if (forceWalkIfDue()) {
            beginWalk(2500, gen, () => { chainLeft = 3 + Math.floor(Math.random() * 3); setTimeout(step, 600); });
            return;
          }

          const name = pickIdleAct();
          const v = videoFor(name);
          if (!v || v.readyState < 2) { setTimeout(step, 900); return; }

          // 1) 停顿：保持上一段的末帧不动（不再定格下一段首帧，那一下最像"强切"）
          logTrace("still:" + name);
          pet.mode = "idle"; // 演动作时绝不能处于 walk，否则 tick 会继续位移
          diag.idle = "still " + name;

          // 串内衔接要快（0.15–0.3 秒），只在串尾才多停一会儿，否则末帧看着像待机呼吸
          const still = chainLeft > 1 ? 150 + Math.random() * 150 : 600 + Math.random() * 400;
          // 动作实际约 9 秒；锁必须盖住整段，否则中途会被主循环切回待机（表现为"转头"）
          pet.animLock = performance.now() + 60000;

          // 2) 停顿结束，淡入并开始演
          setTimeout(() => {
            if (gen !== idleGen) { idleBusy = false; return; }
            try { v.currentTime = TRIM_START; } catch { /* 未就绪 */ }
            v.playbackRate = ANIM_RATE;
            v.play().catch(() => {});
            showVideo(name, 500);
            v.loop = false; // 必须在 showVideo 之后：它会把 loop 设回 true
            logTrace("play:" + name);
            diag.idle = "play " + name;

            // 以视频自己的结束为准（素材时长不可信，按固定值切会截断）
            v.loop = false;
            const startedAt = performance.now();
            let lastT = -1;
            let lastProgressAt = performance.now();
            let trimmed = false;
            const waitEnd = () => {
              if (gen !== idleGen) { idleBusy = false; return; }
              const now = performance.now();
              if (v.currentTime > lastT + 0.01) { lastT = v.currentTime; lastProgressAt = now; }
              // 卡顿不视为播完：轻推一下播放位置让它继续（素材 10 秒，中途顿一下很正常）
              const dur = isFinite(v.duration) ? v.duration : 10;
              if (!trimmed && v.currentTime >= dur - TRIM_END) {
                trimmed = true;
                logTrace("end:" + name + " trim t=" + Math.round(v.currentTime * 10) / 10);
                v.pause();
              }
              const stalledMs = now - lastProgressAt;
              if (v.readyState >= 2 && stalledMs > 1500 && stalledMs < 2600 && !v.ended) {
                try {
                  v.currentTime = Math.min((v.duration || 10) - 0.05, v.currentTime + 0.05);
                  v.play().catch(() => {});
                } catch { /* ignore */ }
              }
              if (!v.ended && !trimmed && now - startedAt < 30000) {
                setTimeout(waitEnd, 100);
                return;
              }
              const stalled = !trimmed && stalledMs > 1500;
              if (!trimmed) {
                logTrace("end:" + name + (v.ended ? " ended" : stalled ? " stall" : " cap") +
                  " t=" + Math.round(v.currentTime * 10) / 10 + "/" + (isFinite(v.duration) ? Math.round(v.duration * 10) / 10 : "?"));
              }
              pet.animLock = 0;
              diag.idle = "next after " + name;
              chainLeft -= 1;
              if (chainLeft > 0) {
                step(); // 直接进入下一段的定格帧
                return;
              }
              // 一串结束：跑动 70% / 歇息 30%
              const linger = 1200 + Math.random() * 800; // 结尾定格，让收尾动作看清
              pet.animLock = performance.now() + linger + 4000;
              setTimeout(() => {
              if (gen !== idleGen) { idleBusy = false; return; }
              // 串尾一律走位，不回待机（待机呼吸自带头部晃动，看着像插入空转）
              beginWalk(2000 + Math.random() * 2500, gen, () => {
                chainLeft = 3 + Math.floor(Math.random() * 3);
                setTimeout(step, 1200 + Math.random() * 800);
              });
              }, linger);
            };
            waitEnd();
          }, still);
        };

        step();
      }

      // 至少每小时挪一次：记录最后一次移动时间
      let lastMoveAt = Date.now();

      function beginWalk(ms, token, done) {
        logTrace("walk:" + Math.round(ms));
        pet.animLock = 0;
        pet.mode = "walk";
        pet.targetX = 80 + Math.random() * Math.max(40, W() - 160);
        lastMoveAt = Date.now();
        const wv = videoFor("walk");
        if (wv) {
          try { if (wv.ended || wv.currentTime >= (wv.duration || 0) - 0.05) wv.currentTime = 0; } catch { /* ignore */ }
          wv.loop = true;
          wv.playbackRate = ANIM_RATE;
          wv.play().catch(() => {});
        }
        fadeTo("walk", 450); // 先淡入走路动画，再位移
        setTimeout(() => {
          if (token !== undefined && token !== idleGen) { idleBusy = false; return; }
          pet.mode = "idle";
          fadeTo("idle", 400); // 走完淡回待机，避免 tick 硬切
          if (done) done();
        }, ms);
      }

      function startWalk() {
        pet.mode = "walk";
        pet.targetX = 80 + Math.random() * Math.max(40, W() - 160);
        lastMoveAt = Date.now();
      }

      function forceWalkIfDue() {
        if (pet.asleep) return false;
        const gap = Date.now() - lastMoveAt;
        if (gap < 55 * 60 * 1000) return false; // 快到一小时了才强制
        startWalk();
        return true;
      }

      // 走动配额：每 30 分钟最多自己走两次
      const WALK_QUOTA = { windowMs: 30 * 60 * 1000, max: 2 };
      function takeWalk() {
        let q = { start: 0, count: 0 };
        try { q = JSON.parse(localStorage.getItem("pet-overlay.walkQuota") || "{}"); } catch { /* ignore */ }
        if (!q.start || Date.now() - q.start > WALK_QUOTA.windowMs) {
          q = { start: Date.now(), count: 0 };
        }
        if (q.count >= WALK_QUOTA.max) return false;
        q.count += 1;
        try { localStorage.setItem("pet-overlay.walkQuota", JSON.stringify(q)); } catch { /* ignore */ }
        return true;
      }

      function decide(now) {
        // 5–12 分钟才决定一次；走不走还受「半小时两次」的配额约束
        pet.nextDecision = now + 5 * 60 * 1000 + Math.random() * 7 * 60 * 1000;
        if (pet.animLock && now < pet.animLock) { pet.mode = "idle"; return; } // 正在演动作，别走
        if (Math.random() < 0.5) pet.lookFor = now + 3000;
        if (takeWalk()) {
          startWalk();
        } else {
          pet.mode = "idle";
        }
      }

      let last = 0;
      function tick(now) {
        const dt = Math.min(32, now - (last || now));
        last = now;
        pet.bob += dt * 0.0026;

        if (pet.lookFor && now > pet.lookFor) pet.lookFor = 0;
        if (pet.hold && pet.mode === "walk") pet.mode = "idle";
        if (!pet.dragging) {
          if (pet.hold || (pet.mode !== "walk" && pet.animLock && now < pet.animLock)) {
            /* 说话/演动作中：不走路、不重新决定 */
          } else if (pet.mode === "walk") {
            const dx = pet.targetX - pet.x;
            const speed = 0.085 * dt;
            if (Math.abs(dx) > 2) {
              pet.x += Math.sign(dx) * Math.min(Math.abs(dx), speed);
              pet.flip = dx > 0 ? 1 : -1;
            } else pet.mode = "idle";
          } else if (now > pet.nextDecision) decide(now);

        }

        pet.pop = Math.max(0, pet.pop - dt * 0.004);
        pet.squash += ((pet.dragging ? 0.94 : 1) - pet.squash) * 0.18;
        pet.x = Math.max(60, Math.min(W() - 60, pet.x));

        const locked = pet.animLock && now < pet.animLock;
        if (!locked) {
          setAnim(pet.mode === "walk" ? "walk" : "idle");
        }
        ctx2d.clearRect(0, 0, W(), H());
        if (animOk) {
          const w = Math.round(PET_H * 1.15);
          stage.style.width = w + "px";
          stage.style.height = w + "px";
          stage.style.left = Math.round(pet.x - w / 2) + "px";
          stage.style.top = Math.round(pet.y - w * 0.92) + "px";
          // 素材默认朝左：向右走时要镜像
          stage.style.transform = pet.flip > 0 ? "scaleX(-1)" : "none";
        } else {
          draw(pet, now);
        }
        placeBubble();
        placeHit();
        placeSayBar();
        requestAnimationFrame(tick);
      }

      // 点它：冒一句话；拖它：跟着走。
      // 做法：宠物身上盖一块透明命中区（touch-action:none），
      // 手势从一开始就归我们，不会被页面滚动抢走。
      let down = null;
      let longPress = null;
      let longPressFired = false;
      const HIT_W = Math.round(PET_H * 0.95);
      const HIT_H = Math.round(PET_H * 1.15);

      const placeHit = () => {
        hit.style.left = Math.round(pet.x - HIT_W / 2) + "px";
        hit.style.top = Math.round(pet.y - HIT_H * 0.82) + "px";
        hit.style.width = HIT_W + "px";
        hit.style.height = HIT_H + "px";
      };

      hit.addEventListener("pointerdown", (e) => {
        down = {
          id: e.pointerId,
          sx: e.clientX, sy: e.clientY,
          moved: 0,
          offX: pet.x - e.clientX, offY: pet.y - e.clientY,
          t: performance.now(),
        };
        longPressFired = false;
        clearTimeout(longPress);
        longPress = setTimeout(() => {
          if (!down) return;
          if (down.moved > 10) return; // 动了就不算长按
          longPressFired = true;
          clearTimeout(longPress);
          openMenu();
        }, 550);
        try { hit.setPointerCapture(e.pointerId); } catch { /* ignore */ }
        e.preventDefault();
      });

      hit.addEventListener("pointermove", (e) => {
        if (!down || e.pointerId !== down.id) return;
        down.moved = Math.max(down.moved, Math.hypot(e.clientX - down.sx, e.clientY - down.sy));
        if (!pet.dragging) {
          if (down.moved < 10) return;
          pet.dragging = true;
          pet.mode = "drag";
          hit.style.cursor = "grabbing";
          document.documentElement.style.userSelect = "none";
          document.documentElement.style.webkitUserSelect = "none";
        }
        e.preventDefault();
        pet.x = e.clientX + down.offX;
        pet.y = Math.min(pet.baseY, Math.max(60, e.clientY + down.offY));
      });

      const endDrag = (cancelled) => {
        clearTimeout(longPress);
        if (!down) return;
        const quick = !pet.dragging && !cancelled && performance.now() - down.t < 400;
        if (pet.dragging) {
          // 放在哪就待在哪，不再掉回地面
          pet.mode = "idle";
        }
        try { hit.releasePointerCapture(down.id); } catch { /* ignore */ }
        pet.dragging = false;
        hit.style.cursor = "grab";
        down = null;
        document.documentElement.style.userSelect = "";
        document.documentElement.style.webkitUserSelect = "";
        if (quick && !longPressFired) {
          touch();
          if (pet.asleep) { wakeUp(); return; }
          pet.pop = 1;
          const CLICK_ANIMS = ["clickHappy", "clickShy", "clickTickle", "clickTsun", "clickWave"];
          const pick = CLICK_ANIMS[Math.floor(Math.random() * CLICK_ANIMS.length)];
          // 这些素材每段都是 10.042 秒的循环（EBML Duration=10042ms），按真实长度放完再淡出
          const CLICK_MS = CLIP_MS;
          const cv = vids[pick];
          if (cv) {
            cv.loop = true;
            cv.playbackRate = ANIM_RATE;
            // 不做 currentTime=0 重定位：跳转要等解码，会带来 0.3s 左右延迟
            cv.play().catch(() => {});
          }
          setAnim(pick);
          // 强制显示：setAnim 可能因 animName 相同而提前返回，透明度停在 0
          animName = pick;
          animOk = true;
          for (const [k2, el2] of Object.entries(vids)) el2.style.opacity = k2 === pick ? "1" : "0";
          stage.style.display = "block";
          idleGen += 1; // 打断待机循环
          const seq = (pet.animSeq = (pet.animSeq || 0) + 1);
          pet.animLock = performance.now() + CLICK_MS + 2000; // 锁到淡出之后，防 tick 抢跑
          setTimeout(() => {
            if (pet.animSeq !== seq) return; // 期间又点过，这次的定时器作废
            pet.animLock = 0;
            fadeTo("idle");
            setTimeout(() => { idleBusy = false; idleLoop(); }, 1200);
          }, CLICK_MS);
          if (menu.classList.contains("open") || sayBar.classList.contains("open")) {
            closeMenu();
            closeSayBar();
          } else {
            showBubble(pickLine());
          }
        }
        pet.nextDecision = performance.now() + 2500;
      };

      hit.addEventListener("pointerup", () => endDrag(false));
      hit.addEventListener("pointercancel", () => endDrag(true));
      hit.addEventListener("lostpointercapture", () => { if (pet.dragging) endDrag(true); });

      loadRemoteList().then(() => {
        // 先只建待机与张望，保证开屏不被十几个解码拖住
        videoFor("idle");
        videoFor("look");
        videoFor("walk"); // 跑动常用，先备好，避免切过去时闪
        setAnim("idle");
        setTimeout(idleLoop, 6000); // 开屏 6 秒后进入待机循环

        // 待机稳定后，串行预热点击那 5 段（内联，本地解码），点下去才不用等
        const WARM = ["clickHappy", "clickShy", "clickTickle", "clickTsun", "clickWave"];
        let wi = 0;
        const warmStep = () => {
          if (wi >= WARM.length) return;
          videoFor(WARM[wi]);
          wi += 1;
          setTimeout(warmStep, 350);
        };
        setTimeout(warmStep, 800);

        // 再往后预热待机动作（远端素材），避免第一次演时闪一下
        setTimeout(() => {
          const WARM_LIST = [
            "look", "hum", "bubble", "stretch", "yawn", "cat", "mirror", "swing",
            "juggle", "rubik", "toycar", "icecream", "watergun", "float", "startled",
            "nap", "sad", "cheer", "dance", "sway", "sleep", "sleepEnd",
            "mealBreakfast", "mealLunch", "mealWatermelon", "mealDinner", "mealHotpot",
            "horseride", "shuttle", "top", "kite", "balloon", "gift", "fan", "gomoku",
            "poker", "curtsy", "dressup", "brush", "whale", "ghost", "animals",
            "flowers", "dove", "bloom", "kawaiiDance", "violin", "flute", "spin",
            "think", "busy", "code", "archive", "record", "cheer", "pace",
            "mooncake", "xmas", "redpacket", "fireworks", "lantern", "riverLantern",
            "snowman", "halloween", "chrysanthemum", "qixi", "lion", "fu",
          ];
          let ai = 0;
          const idleWarm = () => {
            if (ai >= WARM_LIST.length) return;
            videoFor(WARM_LIST[ai]);
            ai += 1;
            setTimeout(idleWarm, 500);
          };
          idleWarm();
        }, 3500);
      });
      resize();
      requestAnimationFrame(tick);
      showBubble("我来了。");
      try {
        window.__petOverlay = Object.assign(window.__petOverlay || {}, {
          say: (t) => say(ctx, t),
          showBubble,
          onReply(text) {
            replySeq += 1;
            try { stopWorking("cheer"); } catch { /* ignore */ }
            showBubble(text.length > 48 ? text.slice(0, 48) + "…" : text);
          },
        });
        setupContext();
        setupProactive();
        setInterval(remindersTick, 20000);
        watchConversation(ctx, showBubble);
      } catch (e) {
        diag.err = "mount-tail:" + ((e && e.name) || "?") + ":" + ((e && e.message) || "").slice(0, 40);
      }
    }

    function apply(ctx) {
      try {
        if (typeof document === "undefined") return;
        if (document.body) mount(ctx);
        else document.addEventListener("DOMContentLoaded", () => mount(ctx), { once: true });
      } catch (err) {
        console.warn("[pet-overlay] mount failed:", err);
      }
    }

    exports.apply = apply;
    // cordis 依赖声明：不写这里，访问 ctx.sessions / ctx.remote 会抛 "without inject"
    exports.inject = ["sessions", "remote", "remote.session"];
    return module.exports;
  },
});
